const D = { energy:.5, scale:1, hue:300, sun:.6, grid:.5, relief:.5, palms:.3, stars:.6, x:.5, y:.5, speed:1, density:.5, style:'synthwave', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const W=width,H=height,t=K.t,en=P.energy,sty=P.style,TAU=Math.PI*2;
const horizon = H*(0.5 + (P.y-0.5)*0.5);
const dc = drawingContext;

// palette
let skyTop=[P.hue,80,22], skyBot=[(P.hue+40)%360,85,55], sunA=[(P.hue-40+360)%360,90,100], sunB=[(P.hue+10)%360,95,80], gridc=[(P.hue+140)%360,90,90], hillc=[(P.hue+180)%360,50,18], starc=[0,0,100], glowC=[(P.hue+20)%360,90,70];
if(sty==='miami'){ skyTop=[250,55,25]; skyBot=[330,70,70]; sunA=[190,80,98]; sunB=[330,80,92]; gridc=[175,80,92]; hillc=[280,50,16]; glowC=[330,70,80]; }
else if(sty==='vapor'){ skyTop=[280,35,55]; skyBot=[190,40,88]; sunA=[320,35,100]; sunB=[190,45,95]; gridc=[300,30,95]; hillc=[250,25,55]; glowC=[300,40,90]; }
else if(sty==='noir'){ skyTop=[220,50,14]; skyBot=[210,45,40]; sunA=[210,20,92]; sunB=[210,35,60]; gridc=[205,25,80]; hillc=[215,40,10]; starc=[210,15,95]; glowC=[210,30,60]; }
else if(sty==='cosmos'){ skyTop=[255,75,10]; skyBot=[275,60,30]; sunA=[315,70,95]; sunB=[265,70,55]; gridc=[190,70,80]; hillc=[260,55,10]; glowC=[300,60,60]; }
else if(sty==='ember'){ skyTop=[250,40,14]; skyBot=[20,85,60]; sunA=[45,90,100]; sunB=[15,90,80]; gridc=[30,80,85]; hillc=[15,50,10]; glowC=[25,85,75]; }
function Cc(a,al){ return color(a[0],a[1],a[2],(al==null?100:al)*P.alpha/100); }

// ---- sky gradient (cheap, canvas2d)
let g=dc.createLinearGradient(0,0,0,horizon);
g.addColorStop(0, Cc(skyTop,100).toString()); g.addColorStop(1, Cc(skyBot,100).toString());
dc.fillStyle=g; noStroke(); rect(0,0,W,horizon+1);
// ground gradient (below horizon, dark)
let g2=dc.createLinearGradient(0,horizon,0,H);
g2.addColorStop(0, Cc([skyBot[0],60,22],100).toString()); g2.addColorStop(1, Cc([P.hue,70,7],100).toString());
dc.fillStyle=g2; rect(0,horizon,W,H-horizon+1);

// ---- stars
if(P.stars>0.05 && sty!=='vapor'){ noStroke();
  const ns=Math.floor(P.stars*120);
  for(let i=0;i<ns;i++){ const sx=fr(i)*W, sy=fr(i+99)*horizon*0.85; const tw=0.5+0.5*Math.sin(t*(1+fr(i)*3)+fr(i)*TAU);
    fill(Cc(starc, 40+tw*55)); circle(sx,sy, (0.6+fr(i+7)*1.4)); } }

// ---- sun with scanline gaps
const sr = (0.10+P.sun*0.22)*Math.min(W,H);
const sunx=P.x*W, suny=horizon - sr*0.35;
dc.save(); dc.shadowBlur=40; dc.shadowColor=Cc(glowC,90).toString();
let sg=dc.createLinearGradient(0,suny-sr,0,suny+sr);
sg.addColorStop(0, Cc(sunA,100).toString()); sg.addColorStop(1, Cc(sunB,100).toString());
dc.fillStyle=sg;
dc.beginPath(); dc.arc(sunx,suny,sr,0,TAU); dc.fill();
dc.restore();
// scanline gaps on lower half
noStroke();
for(let i=0;i<8;i++){ const yy=suny + sr*(0.15 + i*0.11); const gh=(i+1)*0.9;
  fill(Cc(skyBot,100)); rect(sunx-sr, yy, sr*2, gh); }
// reflection glow on horizon
fill(Cc(glowC, 30)); ellipse(sunx, horizon, sr*2.4, sr*0.5);

// ---- silhouette relief (mountains / city)
noStroke(); fill(Cc(hillc,100));
if(P.relief>0.5){ // city skyline
  let xx=0; while(xx<W){ const bw=8+fr(xx*0.3)*38*(0.5+P.grid); const bh=(0.04+fr(xx*0.7)*0.30*P.relief)*H;
    rect(xx, horizon-bh, bw, bh+2);
    // a few lit windows
    fill(Cc(glowC,70)); for(let wy=horizon-bh+4; wy<horizon-4; wy+=7){ if(fr(xx+wy)>0.6) rect(xx+3, wy, bw-6, 2); } fill(Cc(hillc,100));
    xx+=bw+2; }
} else { // mountains
  beginShape(); vertex(0,horizon); let px=0; while(px<=W){ const pk=horizon-(0.02+fr(px*0.5)*0.22*(1-P.relief*0.3)+P.relief*0.08)*H; vertex(px,pk); px+=W/16; } vertex(W,horizon); endShape(CLOSE);
}

// ---- neon perspective grid floor (scrolls toward viewer)
const vpx=sunx, gcol=Cc(gridc,80);
stroke(gcol); strokeWeight(1.4); noFill();
const nv = 8 + Math.floor(P.grid*16);
for(let i=-nv;i<=nv;i++){ const fx = vpx + (i/nv)*W*0.9; line(vpx, horizon, fx, H); }
// horizontal lines with 1/z spacing, scrolling
const scroll = (t*(0.15+en*0.5)*P.speed)%1;
for(let i=0;i<26;i++){ const z=(i+scroll)/26; const yy=horizon + (H-horizon)*(z*z); if(yy>horizon){ strokeWeight(0.8+z*1.8); stroke(Cc(gridc, 30+z*60)); line(0,yy,W,yy); } }
strokeWeight(1);

// ---- palms
if(P.palms>0.05){ const npm=Math.floor(1+P.palms*4); noStroke();
  for(let i=0;i<npm;i++){ const px=(0.1+fr(i*3)*0.8)*W; const ph=(0.16+fr(i)*0.14)*H*(0.6+P.palms); const pby=horizon+ (H-horizon)*0.02;
    const sway2=Math.sin(t*0.7+i)*0.05;
    stroke(Cc(hillc,100)); strokeWeight(3+ph*0.02); noFill();
    push(); translate(px,pby); rotate(sway2);
    line(0,0,0,-ph);
    // fronds
    stroke(Cc([hillc[0],40,12],100)); strokeWeight(2);
    for(let f=0;f<7;f++){ const fa=-Math.PI/2 + (f-3)*0.4; const fl=ph*0.5; push(); translate(0,-ph); rotate(fa+sway2);
      beginShape(); vertex(0,0); bezierVertex(fl*0.4,-4, fl*0.8,2, fl,6); endShape(); pop(); }
    pop(); noStroke(); }
  stroke(1); noStroke();
}
blendMode(BLEND); dc.shadowBlur=0;
